#pragma once

// Native behaviour of the shape blocks generated by tools/pack/lib.ps1 (New-ShapeSet,
// New-WoodSet, New-DoorBlock, ...). It applies to ANY block carrying the generator's tags, so
// feature units get vanilla-like stairs, slabs, walls, fences, doors... without code of their own.
//
// Block contract (written by the generator; see tools/pack/README.md):
//
//   tag                    states                                         native behaviour
//   lepton:stairs          minecraft:cardinal_direction (trait; the high   corner shape from the
//                          side, = the player's look direction),           neighbours, like Java
//                          minecraft:vertical_half (trait),
//                          lepton:shape straight|inner_left|inner_right|outer_left|outer_right
//   lepton:slab            minecraft:vertical_half (trait), lepton:double  slab + same slab = double
//   lepton:vertical_slab   lepton:type north|south|west|east|double        Quark placement + merging
//                          (Quark's VerticalSlabType: the open side; the
//                          slab fills the opposite half)
//   lepton:wall            lepton:north|east|south|west none|short|tall,   connections, tall sides,
//                          lepton:post                                     post like Java walls
//   lepton:fence           lepton:north|east|south|west (bool)             connections
//   lepton:pane            lepton:north|east|south|west (bool)             connections
//   lepton:fence_gate      minecraft:cardinal_direction, lepton:open,      open/close on use and by
//                          lepton:in_wall                                  redstone, lowered in walls
//   lepton:door            minecraft:cardinal_direction, lepton:open,      two halves, hinge, open
//                          lepton:upper, lepton:hinge_right                on use (unless
//                                                                          lepton:redstone_only) and
//                                                                          by redstone
//   lepton:trapdoor        minecraft:cardinal_direction, minecraft:        Java placement, open on
//                          vertical_half, lepton:open                      use / by redstone
//   lepton:button          minecraft:block_face (trait), lepton:pressed    pressed on use for
//                                                                          lepton:press_ticks_<n>
//   lepton:pressure_plate  lepton:pressed                                  pressed while an entity
//                                                                          stands on it (players and
//                                                                          mobs only with
//                                                                          lepton:mobs_only)
//   lepton:pillar          minecraft:block_face (trait)                    (data only: axis model)
//   lepton:strippable      (any)                                           an axe turns
//                                                                          lepton:<x> into
//                                                                          lepton:stripped_<x>
//   lepton:wooden          -                                               wooden fences connect to
//                                                                          wooden fences only
//
// Pressed buttons/plates emit redstone through minecraft:redstone_producer (block JSON). Doors,
// trapdoors and gates react to redstone sources next to them (an approximation: blocks powered
// "through" another block are not detected).
//
// Everything runs on the server thread; client-side levels are ignored.

#include <functional>
#include <optional>
#include <string>
#include <string_view>

class Block;
class BlockPos;
class BlockSource;
class Player;
class Vec3;

namespace lp::game::shapes {

enum class Kind {
    None,
    Stairs,
    Slab,
    VerticalSlab,
    Wall,
    Fence,
    FenceGate,
    Pane,
    Door,
    Trapdoor,
    Button,
    PressurePlate,
    Pillar,
};

/// The generator kind of `block` (from its lepton:<kind> tag); Kind::None for other blocks.
[[nodiscard]] Kind             kindOf(Block const& block);
[[nodiscard]] std::string_view kindName(Kind kind);
/// A generated slab or vertical slab.
[[nodiscard]] bool isSlab(Block const& block);
/// A merged (double) slab or vertical slab.
[[nodiscard]] bool isDouble(Block const& block);

/// Horizontal direction names: "north", "south", "west", "east".
[[nodiscard]] std::string_view opposite(std::string_view dir);
[[nodiscard]] std::string_view clockwise(std::string_view dir);
[[nodiscard]] std::string_view counterClockwise(std::string_view dir);
/// The direction an actor with this yaw looks along (Java getHorizontalDirection).
[[nodiscard]] std::string_view lookDirection(float yaw);
/// Bedrock FacingID (0 down, 1 up, 2 north, 3 south, 4 west, 5 east) -> name ("up", "north", ...).
[[nodiscard]] std::string_view faceName(int face);
/// `pos` moved one block towards `dir` (horizontal names, "up", "down").
[[nodiscard]] BlockPos neighbor(BlockPos const& pos, std::string_view dir);
/// The facing of a stairs/gate/door/trapdoor (lepton or vanilla), if it has one.
[[nodiscard]] std::optional<std::string> facingOf(Block const& block);

/// Quark's vertical slab placement: `face` is the clicked face (FacingID), `hit` the click
/// position relative to the PLACED block's corner. Returns the lepton:type value.
[[nodiscard]] std::string verticalSlabType(int face, Vec3 const& hit);

/// Recomputes the derived states of the shape at `pos` now (stairs shape, connections, wall
/// posts, gate in_wall, door halves, redstone). Returns true if the block changed.
bool updateShape(BlockSource& region, BlockPos const& pos);
/// Queues `pos` and its 6 neighbours for `updateShape` at the end of this tick.
void queueUpdate(BlockSource& region, BlockPos const& pos);

/// A redstone source next to `pos` (see the header comment for the approximation).
[[nodiscard]] bool isPowered(BlockSource& region, BlockPos const& pos);
/// Opens / closes a door (both halves), trapdoor or fence gate. `by` (optional) is the player
/// who uses it: an opening gate swings away from them. Plays the sound. False if not openable.
bool setOpen(BlockSource& region, BlockPos const& pos, bool open, Player* by = nullptr);
/// Presses a button or pressure plate (released automatically). False if not pressable.
bool press(BlockSource& region, BlockPos const& pos);

/// Extra connection rule for the generated walls, panes and fences (added for U1 VerticalSlabs:
/// walls/panes connect to the side of vertical slabs). `self` is the kind being updated
/// (Kind::Wall, Kind::Pane or Kind::Fence), `other` the neighbour and `face` the neighbour's face
/// that points at `self` ("north", ...). Return true to connect; the rules are OR-ed with the
/// built-in ones. Register in install(); the returned id removes the rule in uninstall().
using ConnectRule = std::function<bool(Kind self, Block const& other, std::string_view face)>;
int  addConnectRule(ConnectRule rule);
void removeConnectRule(int id);

} // namespace lp::game::shapes
